create or replace function public.enforce_notification_delivery_message_limits() returns trigger language plpgsql set search_path=public as $$ begin if lower(coalesce(new.canal,'')) = 'sms' and char_length(regexp_replace(btrim(coalesce(new.contenu,'')), '\s+', ' ', 'g')) > 155 then raise exception 'Le SMS ne peut pas dépasser 155 caractères, espaces et signes compris.'; end if; if lower(coalesce(new.canal,'')) = 'whatsapp' and char_length(coalesce(new.contenu,'')) > 350 then raise exception 'Le message WhatsApp ne peut pas dépasser 350 caractères.'; end if; return new; end $$; drop trigger if exists notification_deliveries_message_limits on public.notification_deliveries; create trigger notification_deliveries_message_limits before insert or update of canal,contenu on public.notification_deliveries for each row execute function public.enforce_notification_delivery_message_limits();